mapper.select:
SELECT id, tenant_id, applicant_user_id, supplier_name, status, state_version, created_at, updated_at
FROM supplier_applications
WHERE id = #{id, jdbcType=OTHER}

mapper.update:
UPDATE supplier_applications
SET status = #{status}, state_version = state_version + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id, jdbcType=OTHER}
  AND tenant_id = #{tenantId}
  AND state_version = #{stateVersion}
